import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  ArcElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';
import { Line, Bar } from 'react-chartjs-2';

// Import Modular Components
import Dashboard from './components/Dashboard';
import DataManagement from './components/Datamanagement';
import ModelTraining from './components/Modeltraining';
import Predictions from './components/Prediction';
import Recommendations from './components/Recommendations';
import Login from './components/Login';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  ArcElement,
  Title,
  Tooltip,
  Legend
);

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

function App() {
  const [user, setUser] = useState(() => {
    try {
      const saved = localStorage.getItem('climayield_user');
      return saved ? JSON.parse(saved) : null;
    } catch {
      return null;
    }
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const userRole = user?.role === 'dev' ? 'dev' : 'farmer';
  const [backendOnline, setBackendOnline] = useState(false);
  const [systemStatus, setSystemStatus] = useState({
    datasetLoaded: false,
    trainingStatus: {
      sarima: 'Not Trained',
      lstm: 'Not Trained',
      hybrid: 'Not Trained'
    },
    datasetShape: null
  });

  // Weather Monitor State — Live data from Open-Meteo API (Quezon City)
  const [showWeatherDetails, setShowWeatherDetails] = useState(false);
  const [selectedDay, setSelectedDay] = useState(0);
  const [weatherData, setWeatherData] = useState(null);
  const [weatherLoading, setWeatherLoading] = useState(false);
  const [weatherLastUpdated, setWeatherLastUpdated] = useState(null);

  // Quezon City coordinates
  const QC_LAT = 14.6760;
  const QC_LON = 121.0437;

  // WMO Weather Code → human-readable condition
  const wmoCodeToCondition = (code) => {
    if (code === 0) return 'Clear Sky';
    if (code === 1) return 'Mainly Clear';
    if (code === 2) return 'Partly Cloudy';
    if (code === 3) return 'Overcast';
    if (code >= 45 && code <= 48) return 'Fog';
    if (code >= 51 && code <= 55) return 'Drizzle';
    if (code >= 56 && code <= 57) return 'Freezing Drizzle';
    if (code >= 61 && code <= 63) return 'Light Rain';
    if (code === 65) return 'Heavy Rain';
    if (code >= 66 && code <= 67) return 'Freezing Rain';
    if (code >= 71 && code <= 77) return 'Snow';
    if (code >= 80 && code <= 82) return 'Rain Showers';
    if (code >= 85 && code <= 86) return 'Snow Showers';
    if (code === 95) return 'Thunderstorm';
    if (code >= 96 && code <= 99) return 'Thunderstorm with Hail';
    return 'Unknown';
  };

  const wmoCodeToIcon = (code) => {
    if (code === 0) return '☀️';
    if (code === 1) return '🌤️';
    if (code === 2) return '⛅';
    if (code === 3) return '☁️';
    if (code >= 45 && code <= 48) return '🌫️';
    if (code >= 51 && code <= 57) return '🌦️';
    if (code >= 61 && code <= 63) return '🌦️';
    if (code === 65) return '🌧️';
    if (code >= 66 && code <= 67) return '🌧️';
    if (code >= 71 && code <= 77) return '❄️';
    if (code >= 80 && code <= 82) return '🌧️';
    if (code >= 85 && code <= 86) return '🌨️';
    if (code === 95) return '⛈️';
    if (code >= 96 && code <= 99) return '⛈️';
    return '🌤️';
  };

  // Wind direction degrees → compass label
  const degreesToCompass = (deg) => {
    const dirs = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE', 'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW'];
    return dirs[Math.round(deg / 22.5) % 16];
  };

  // Generate smart agronomic alerts based on live weather
  const generateAlerts = (current, daily) => {
    const alerts = [];
    // Heavy rain warning
    const heavyRainDays = daily.time
      .map((t, i) => ({ day: new Date(t).toLocaleDateString('en-US', { weekday: 'long' }), rain: daily.precipitation_sum[i] }))
      .filter(d => d.rain >= 15);
    if (heavyRainDays.length > 0) {
      alerts.push({
        type: 'warning',
        message: `Heavy rainfall (${heavyRainDays[0].rain} mm) expected on ${heavyRainDays[0].day}. Clear drainage channels and secure seedlings.`
      });
    }
    // High UV warning
    const todayUV = daily.uv_index_max[0];
    if (todayUV >= 8) {
      alerts.push({
        type: 'warning',
        message: `Very high UV index today (${todayUV.toFixed(1)}). Protect sensitive nursery beds with shade netting.`
      });
    } else if (todayUV >= 6) {
      alerts.push({
        type: 'info',
        message: `High UV index today (${todayUV.toFixed(1)}). Consider afternoon shade for newly transplanted seedlings.`
      });
    }
    // Dry spell opportunity
    const dryDays = daily.precipitation_sum.filter(r => r < 1.0).length;
    if (dryDays >= 3) {
      alerts.push({
        type: 'success',
        message: `${dryDays} dry days in the 7-day outlook — good window for field preparation and pesticide application.`
      });
    }
    // High humidity advisory
    if (current.relative_humidity_2m >= 85) {
      alerts.push({
        type: 'info',
        message: `Humidity is very high (${current.relative_humidity_2m}%). Monitor crops for fungal disease pressure.`
      });
    }
    // Optimal planting
    const optimalDays = daily.time
      .map((t, i) => ({ day: new Date(t).toLocaleDateString('en-US', { weekday: 'short' }), rain: daily.precipitation_sum[i], maxT: daily.temperature_2m_max[i] }))
      .filter(d => d.rain >= 2 && d.rain <= 10 && d.maxT <= 32);
    if (optimalDays.length >= 2) {
      alerts.push({
        type: 'success',
        message: `Optimal planting moisture expected on ${optimalDays.map(d => d.day).join(', ')}. Good conditions for sowing short-cycle vegetables.`
      });
    }
    return alerts.length > 0 ? alerts : [{ type: 'info', message: 'No special weather advisories for your area at this time.' }];
  };

  // Fetch live weather data from Open-Meteo
  const fetchWeather = useCallback(async () => {
    setWeatherLoading(true);
    try {
      const params = new URLSearchParams({
        latitude: QC_LAT,
        longitude: QC_LON,
        current: 'temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,weather_code,wind_speed_10m,wind_direction_10m,surface_pressure',
        daily: 'weather_code,temperature_2m_max,temperature_2m_min,apparent_temperature_max,precipitation_sum,precipitation_probability_max,wind_speed_10m_max,uv_index_max',
        timezone: 'Asia/Manila',
        forecast_days: 7
      });
      const resp = await fetch(`https://api.open-meteo.com/v1/forecast?${params}`);
      if (!resp.ok) throw new Error(`Weather API error: ${resp.status}`);
      const data = await resp.json();

      const cur = data.current;
      const d = data.daily;
      const dayNames = d.time.map((t, i) => {
        if (i === 0) return 'Today';
        if (i === 1) return 'Tomorrow';
        return new Date(t).toLocaleDateString('en-US', { weekday: 'short' });
      });

      setWeatherData({
        current: {
          temperature: cur.temperature_2m,
          feelsLike: cur.apparent_temperature,
          humidity: cur.relative_humidity_2m,
          rainfall: cur.precipitation,
          windSpeed: cur.wind_speed_10m,
          windDirection: degreesToCompass(cur.wind_direction_10m),
          pressure: cur.surface_pressure,
          uvIndex: d.uv_index_max[0],
          condition: wmoCodeToCondition(cur.weather_code),
          icon: wmoCodeToIcon(cur.weather_code)
        },
        forecast: d.time.map((t, i) => ({
          day: dayNames[i],
          temp: ((d.temperature_2m_max[i] + d.temperature_2m_min[i]) / 2).toFixed(1),
          minTemp: d.temperature_2m_min[i],
          maxTemp: d.temperature_2m_max[i],
          rainfall: d.precipitation_sum[i],
          rainProbability: d.precipitation_probability_max[i],
          windMax: d.wind_speed_10m_max[i],
          condition: wmoCodeToCondition(d.weather_code[i])
        })),
        alerts: generateAlerts(cur, d),
        historical: {
          labels: dayNames,
          rainfall: d.precipitation_sum,
          temperature: d.temperature_2m_max.map((max, i) => ((max + d.temperature_2m_min[i]) / 2).toFixed(1))
        }
      });
      setWeatherLastUpdated(new Date());
    } catch (err) {
      console.error('Weather fetch error:', err);
      toast.error('Failed to fetch live weather data. Retrying...');
    } finally {
      setWeatherLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Auto-fetch weather on mount and every 10 minutes
  useEffect(() => {
    fetchWeather();
    const weatherInterval = setInterval(fetchWeather, 10 * 60 * 1000);
    return () => clearInterval(weatherInterval);
  }, [fetchWeather]);

  // Fetch Live Backend System Status
  const fetchStatus = useCallback(async () => {
    try {
      const res = await axios.get(`${API_URL}/status`, { timeout: 4000 });
      setSystemStatus(res.data);
      setBackendOnline(true);
    } catch (err) {
      setBackendOnline(false);
    }
  }, []);

  useEffect(() => {
    fetchStatus();
    const interval = setInterval(fetchStatus, 8000);
    return () => clearInterval(interval);
  }, [fetchStatus]);

  // Reset Backend State
  const handleReset = async () => {
    if (!window.confirm('Reset all uploaded datasets and model training state on the backend?')) {
      return;
    }
    try {
      await axios.post(`${API_URL}/reset`);
      toast.info('Backend state successfully reset.');
      fetchStatus();
    } catch (err) {
      toast.error('Failed to reset backend state.');
    }
  };

  // Weather Helpers
  const getWeatherIcon = (condition) => {
    const icons = {
      'Sunny': '☀️',
      'Partly Cloudy': '⛅',
      'Cloudy': '☁️',
      'Light Rain': '🌦️',
      'Heavy Rain': '🌧️',
      'Thunderstorm': '⛈️'
    };
    return icons[condition] || '🌤️';
  };

  const getAlertColor = (type) => {
    switch (type) {
      case 'warning': return '#f39c12';
      case 'info': return '#3498db';
      case 'success': return '#27ae60';
      default: return '#7f8c8d';
    }
  };

  const getAlertIcon = (type) => {
    switch (type) {
      case 'warning': return '⚠️';
      case 'info': return 'ℹ️';
      case 'success': return '✅';
      default: return '📢';
    }
  };

  // Weather Monitor Tab Content
  const renderWeatherMonitor = () => (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', flexWrap: 'wrap', gap: '10px' }}>
        <h2>🌤️ Real-Time Weather Monitoring</h2>
        <div style={{ display: 'flex', gap: '10px' }}>
          <button 
            className="btn-secondary"
            onClick={() => setShowWeatherDetails(!showWeatherDetails)}
          >
            {showWeatherDetails ? '📉 Hide Trend Charts' : '📊 Show Trend Charts'}
          </button>
          <button 
            className="btn-secondary"
            onClick={() => toast.info('Weather data refreshed from station sensors.')}
          >
            🔄 Sync Weather
          </button>
        </div>
      </div>

      {/* Current Weather Card */}
      <div className="weather-current" style={{
        background: userRole === 'dev' 
          ? 'linear-gradient(135deg, #1f4d66 0%, #2980b9 100%)' 
          : 'linear-gradient(135deg, #27ae60 0%, #2c3e50 100%)',
        borderRadius: '20px',
        padding: '30px',
        color: 'white',
        marginBottom: '20px',
        boxShadow: '0 8px 25px rgba(0,0,0,0.15)'
      }}>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px' }}>
          <div>
            <h3 style={{ fontSize: '3rem', margin: '0' }}>
              {weatherData.current.temperature}°C
            </h3>
            <p style={{ fontSize: '1.1rem', margin: '5px 0', opacity: 0.9 }}>
              Feels like {weatherData.current.feelsLike}°C
            </p>
            <p style={{ fontSize: '1.4rem', marginTop: '8px' }}>
              {weatherData.current.icon} {weatherData.current.condition}
            </p>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px' }}>
            <div>
              <p style={{ opacity: 0.8, margin: '0', fontSize: '0.9rem' }}>💧 Humidity</p>
              <p style={{ fontSize: '1.3rem', fontWeight: 'bold', margin: '0' }}>
                {weatherData.current.humidity}%
              </p>
            </div>
            <div>
              <p style={{ opacity: 0.8, margin: '0', fontSize: '0.9rem' }}>🌧️ Rainfall</p>
              <p style={{ fontSize: '1.3rem', fontWeight: 'bold', margin: '0' }}>
                {weatherData.current.rainfall} mm
              </p>
            </div>
            <div>
              <p style={{ opacity: 0.8, margin: '0', fontSize: '0.9rem' }}>💨 Wind Speed</p>
              <p style={{ fontSize: '1.3rem', fontWeight: 'bold', margin: '0' }}>
                {weatherData.current.windSpeed} km/h {weatherData.current.windDirection}
              </p>
            </div>
            <div>
              <p style={{ opacity: 0.8, margin: '0', fontSize: '0.9rem' }}>☀️ UV Index</p>
              <p style={{ fontSize: '1.3rem', fontWeight: 'bold', margin: '0' }}>
                {weatherData.current.uvIndex} (High)
              </p>
            </div>
          </div>
          <div style={{ textAlign: 'right' }}>
            <p style={{ margin: '0', fontWeight: '600' }}>
              📅 {new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })}
            </p>
            <p style={{ margin: '6px 0', opacity: 0.85, fontSize: '0.9rem' }}>
              Barometer: {weatherData.current.pressure} hPa
            </p>
            <p style={{ margin: '4px 0', opacity: 0.85, fontSize: '0.9rem' }}>
              Field Visibility: {weatherData.current.visibility} km
            </p>
          </div>
        </div>
      </div>

      {/* Weather Alerts */}
      {weatherData.alerts && (
        <div style={{ marginBottom: '20px' }}>
          <h4>🔔 Agronomic Weather Advisories</h4>
          <div style={{ display: 'grid', gap: '10px', marginTop: '10px' }}>
            {weatherData.alerts.map((alert, idx) => (
              <div key={idx} style={{
                padding: '12px 18px',
                borderRadius: '10px',
                background: `${getAlertColor(alert.type)}15`,
                borderLeft: `4px solid ${getAlertColor(alert.type)}`,
                display: 'flex',
                alignItems: 'center',
                gap: '12px'
              }}>
                <span style={{ fontSize: '1.3rem' }}>{getAlertIcon(alert.type)}</span>
                <span style={{ fontSize: '0.95rem', color: '#2c3e50', fontWeight: '500' }}>{alert.message}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 7-Day Forecast Horizon */}
      <div style={{ marginBottom: '25px' }}>
        <h4>📊 7-Day Meteorological Outlook</h4>
        <div style={{ 
          display: 'grid', 
          gridTemplateColumns: 'repeat(auto-fit, minmax(110px, 1fr))', 
          gap: '12px',
          marginTop: '10px'
        }}>
          {weatherData.forecast.map((day, idx) => (
            <div 
              key={idx} 
              className={`weather-day ${idx === selectedDay ? 'selected' : ''}`}
              style={{
                background: idx === selectedDay ? '#3498db' : 'white',
                color: idx === selectedDay ? 'white' : '#2c3e50',
                padding: '15px 10px',
                borderRadius: '12px',
                textAlign: 'center',
                cursor: 'pointer',
                boxShadow: '0 2px 6px rgba(0,0,0,0.08)',
                border: idx === selectedDay ? 'none' : '1px solid #e0e0e0',
                transition: 'all 0.25s ease'
              }}
              onClick={() => setSelectedDay(idx)}
            >
              <div style={{ fontSize: '1.6rem' }}>{getWeatherIcon(day.condition)}</div>
              <div style={{ fontWeight: 'bold', marginTop: '6px' }}>{day.day}</div>
              <div style={{ fontSize: '1.2rem', fontWeight: 'bold', margin: '4px 0' }}>{day.temp}°</div>
              <div style={{ fontSize: '0.75rem', opacity: 0.8 }}>
                {day.minTemp}° / {day.maxTemp}°
              </div>
              <div style={{ fontSize: '0.75rem', opacity: 0.85, marginTop: '4px' }}>
                💧 {day.humidity}% | 🌧️ {day.rainfall}mm
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Historical Weather Charts */}
      {showWeatherDetails && (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '20px' }}>
          <div className="card">
            <h4>📈 Weekly Rainfall Accumulation (mm)</h4>
            <div className="chart-container" style={{ height: '220px', marginTop: '10px' }}>
              <Bar 
                data={{
                  labels: weatherData.historical.labels,
                  datasets: [{
                    label: 'Rainfall (mm)',
                    data: weatherData.historical.rainfall,
                    backgroundColor: 'rgba(52, 152, 219, 0.7)',
                    borderColor: '#3498db',
                    borderWidth: 1
                  }]
                }}
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  scales: { y: { beginAtZero: true } }
                }}
              />
            </div>
          </div>

          <div className="card">
            <h4>📈 Temperature Fluctuations (°C)</h4>
            <div className="chart-container" style={{ height: '220px', marginTop: '10px' }}>
              <Line 
                data={{
                  labels: weatherData.historical.labels,
                  datasets: [{
                    label: 'Mean Temp (°C)',
                    data: weatherData.historical.temperature,
                    borderColor: '#e74c3c',
                    backgroundColor: 'rgba(231, 76, 60, 0.1)',
                    fill: true,
                    tension: 0.4
                  }]
                }}
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  scales: { y: { beginAtZero: false } }
                }}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );

  // Tab Router
  const renderActiveTab = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            systemStatus={systemStatus} 
            setActiveTab={setActiveTab} 
            onRefresh={fetchStatus} 
          />
        );
      case 'weather':
        return renderWeatherMonitor();
      case 'data':
        return <DataManagement onDataUpload={fetchStatus} />;
      case 'training':
        return <ModelTraining onTrainingComplete={fetchStatus} />;
      case 'predictions':
        return <Predictions />;
      case 'recommendations':
        return <Recommendations />;
      default:
        return (
          <Dashboard 
            systemStatus={systemStatus} 
            setActiveTab={setActiveTab} 
            onRefresh={fetchStatus} 
          />
        );
    }
  };

  // If not authenticated, display the FarmerSide / DevSide Login Component
  if (!user) {
    return (
      <>
        <Login 
          onLoginSuccess={(loggedUser) => {
            setUser(loggedUser);
            try {
              localStorage.setItem('climayield_user', JSON.stringify(loggedUser));
            } catch {}
          }} 
        />
        <ToastContainer position="bottom-right" autoClose={3500} />
      </>
    );
  }

  return (
    <div className={`App theme-${userRole}`}>
      {/* Top Header */}
      <header className="App-header" style={{
        background: userRole === 'dev'
          ? 'linear-gradient(135deg, #1a3b4f 0%, #2980b9 100%)'
          : 'linear-gradient(135deg, #1d341d 0%, #27ae60 100%)'
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '0 30px', flexWrap: 'wrap', gap: '15px' }}>
          <div style={{ textAlign: 'left' }}>
            <h1 style={{ display: 'flex', alignItems: 'center', gap: '12px', margin: 0 }}>
              <span>🌾</span> ClimaYield-X
            </h1>
            <p className="subtitle" style={{ margin: '5px 0 0 0' }}>
              A Data-Driven SARIMA–LSTM Hybrid Model for Predicting Yield Instability in Short-Cycle Vegetables
            </p>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flexWrap: 'wrap' }}>
            {/* User Profile Badge */}
            <div style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: '8px',
              padding: '6px 14px',
              borderRadius: '20px',
              background: 'rgba(255, 255, 255, 0.22)',
              fontSize: '0.85rem',
              color: 'white',
              fontWeight: '600',
              border: '1px solid rgba(255, 255, 255, 0.3)'
            }}>
              <span>{userRole === 'dev' ? '💻' : '🧑‍🌾'}</span>
              <span>{user.name}</span>
              <span style={{
                background: 'rgba(255, 255, 255, 0.25)',
                padding: '2px 8px',
                borderRadius: '12px',
                fontSize: '0.72rem',
                textTransform: 'uppercase',
                letterSpacing: '0.5px'
              }}>
                {userRole === 'dev' ? 'Developer' : 'Farmer'}
              </span>
            </div>

            {/* Backend Connection Indicator */}
            <div style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: '6px',
              padding: '6px 12px',
              borderRadius: '20px',
              fontSize: '0.82rem',
              fontWeight: '600',
              background: backendOnline ? 'rgba(39, 174, 96, 0.25)' : 'rgba(231, 76, 60, 0.25)',
              border: `1px solid ${backendOnline ? '#2ecc71' : '#e74c3c'}`,
              color: 'white'
            }}>
              <span>{backendOnline ? '🟢' : '🔴'}</span>
              <span>{backendOnline ? 'Backend Online' : 'Backend Offline'}</span>
            </div>

            {/* Reset Button */}
            <button 
              onClick={handleReset}
              style={{
                background: 'rgba(255, 255, 255, 0.15)',
                border: '1px solid rgba(255, 255, 255, 0.3)',
                color: 'white',
                padding: '6px 12px',
                borderRadius: '20px',
                cursor: 'pointer',
                fontSize: '0.8rem',
                fontWeight: '600'
              }}
              title="Reset dataset and trained models on backend"
            >
              🔄 Reset Data
            </button>

            {/* Sign Out Button */}
            <button 
              onClick={() => {
                setUser(null);
                try { localStorage.removeItem('climayield_user'); } catch {}
                toast.info('Signed out successfully.');
              }}
              style={{
                background: 'rgba(231, 76, 60, 0.3)',
                border: '1px solid rgba(231, 76, 60, 0.6)',
                color: 'white',
                padding: '6px 12px',
                borderRadius: '20px',
                cursor: 'pointer',
                fontSize: '0.8rem',
                fontWeight: '600'
              }}
            >
              🚪 Sign Out
            </button>
          </div>
        </div>
      </header>

      {/* Tab Navigation */}
      <nav className="nav-tabs">
        <button 
          className={activeTab === 'dashboard' ? 'active' : ''} 
          onClick={() => setActiveTab('dashboard')}
        >
          📊 Dashboard
        </button>
        <button 
          className={activeTab === 'weather' ? 'active' : ''} 
          onClick={() => setActiveTab('weather')}
        >
          🌤️ Weather Monitor
        </button>
        <button 
          className={activeTab === 'data' ? 'active' : ''} 
          onClick={() => setActiveTab('data')}
        >
          📁 Data Management
        </button>
        <button 
          className={activeTab === 'training' ? 'active' : ''} 
          onClick={() => setActiveTab('training')}
        >
          🤖 Model Training
        </button>
        <button 
          className={activeTab === 'predictions' ? 'active' : ''} 
          onClick={() => setActiveTab('predictions')}
        >
          📈 Predictions
        </button>
        <button 
          className={activeTab === 'recommendations' ? 'active' : ''} 
          onClick={() => setActiveTab('recommendations')}
        >
          💡 Recommendations
        </button>
      </nav>

      {/* Main Tab Content */}
      <main className="main-content">
        {renderActiveTab()}
      </main>

      <ToastContainer position="bottom-right" autoClose={3500} />
    </div>
  );
}

export default App;
